// Harborfall — embedded CC0 texture data (split out of cc0Textures.ts
// in Phase 12). This module is imported DYNAMICALLY by the loader in
// cc0Textures.ts, so the ~1.24 MB of base64 data URIs ship as an
// async chunk instead of inside the initial bundle. Low tier never
// requests a CC0 texture, so it never downloads this chunk at all.
const asphaltDiff = "data:image/webp;base64,";
const asphaltNor = "data:image/webp;base64,";
const asphaltRough = "data:image/webp;base64,";
const concreteDiff = "data:image/webp;base64,";
const concreteNor = "data:image/webp;base64,";
const concreteRough = "data:image/webp;base64,";
const brickDiff = "data:image/webp;base64,";
const brickNor = "data:image/webp;base64,";
const brickRough = "data:image/webp;base64,";
const plasterDiff = "data:image/webp;base64,";
const plasterNor = "data:image/webp;base64,";
const plasterRough = "data:image/webp;base64,";

export const CC0_URIS: Record<string, string> = {
  asphaltDiff, asphaltNor, asphaltRough,
  concreteDiff, concreteNor, concreteRough,
  brickDiff, brickNor, brickRough,
  plasterDiff, plasterNor, plasterRough,
};
